$root=dirname(__DIR__);require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';MigrationService::run();require_once $root.'/app/AuthService.php';require_once $root.'/app/BehaviorService.php';require_once $root.'/app/CausalService.php';require_once $root.'/app/DynamicOpportunityService.php';require_once $root.'/app/CharacterAutomationService.php';require_once $root.'/app/StateSyncService.php';require_once $root.'/app/SimulationService.php';require_once $root.'/app/LobbyService.php';AuthService::boot();$user=AuthService::requireLogin();$gid=(int)($_GET['game']??$_POST['game_id']??0);if($gid<1){header('Location: ./');exit;}$error=null;$notice=null;
try{$membership=LobbyService::lobbyState($gid,(int)$user['user_id']);if($membership['game']['status']==='LOBBY'){header('Location: lobby.php?game='.$gid);exit;}}catch(Throwable$e){http_response_code(403);die(e($e->getMessage()));}
if($_SERVER['REQUEST_METHOD']==='POST'){try{AuthService::requireCsrf();$action=(string)($_POST['action']??'');if($action==='decide')LobbyService::choose($gid,(int)$user['user_id'],(int)$_POST['decision_id'],(string)$_POST['option_code']);if($action==='rate'){LobbyService::rate($gid,(int)$user['user_id'],(int)$_POST['rating'],(string)($_POST['review']??''));$notice='Thank you for rating this story.';}header('Location: play.php?game='.$gid.($notice?'&rated=1':''));exit;}catch(Throwable$e){$error=$e->getMessage();}}
try{LobbyService::tick($gid);}catch(Throwable$e){$error=($error?$error.' | ':'').$e->getMessage();}
$state=LobbyService::lobbyState($gid,(int)$user['user_id']);$sid=(int)$state['game']['simulation_id'];$snap=SimulationService::snapshot($sid);$sim=$snap['simulation'];$character=LobbyService::playerCharacter($gid,(int)$user['user_id']);if($character){foreach($snap['characters']as$c)if((int)$c['character_id']===(int)$character['character_id']){$character=$c;break;}}$rated=isset($_GET['rated']);
$playDuration=(int)($state['game']['play_duration_seconds']??$sim['duration_seconds']);$storyDuration=max(1,(int)$sim['duration_seconds']);$wallElapsed=0;if(!empty($state['game']['started_at_utc']))$wallElapsed=min($playDuration,max(0,time()-strtotime((string)$state['game']['started_at_utc'].' UTC')));if($sim['status']==='COMPLETE')$wallElapsed=$playDuration;
$displaySecond=static fn(int $storySecond):int=>(int)round($storySecond*$playDuration/$storyDuration);
$charactersById=[];$otherCharacters=[];foreach($snap['characters']as$c){$charactersById[(int)$c['character_id']]=$c;if(!$character||(int)$c['character_id']!==(int)$character['character_id'])$otherCharacters[]=$c;}
$timeline=[];foreach($snap['world']as$w){$actorId=(int)($w['actor_character_id']??0);if($character&&$actorId===(int)$character['character_id'])continue;$second=(int)$w['event_second'];$timeline[$second]??=['public'=>[],'personal'=>[]];$actor=$charactersById[$actorId]??null;$actorName=(string)($actor['name']??'');$headline=(string)$w['headline'];$detail=player_visible_text((string)$w['event_text']);if($actorName!==''){$passed=stripos($headline,'opportunity pass')!==false;$headline=$passed?$actorName.' Let an Opportunity Pass':$actorName.' Acted';$detail=$passed?'The situation changed without '.$actorName.' intervening.':observer_narrative($actorName,$detail);}$timeline[$second]['public'][]=['label'=>story_phase_label((string)$w['phase']),'title'=>$headline,'detail'=>$detail];}
if($character)foreach($character['history']as$h){$type=(string)$h['history_type'];if($type==='STAT_CHANGE'||strcasecmp((string)$h['title'],'Initial State')===0)continue;$second=(int)$h['event_second'];$timeline[$second]??=['public'=>[],'personal'=>[]];$title=(string)$h['title'];$detail=player_visible_text((string)$h['detail_text']);if($type==='DECISION')$title='You Chose to '.preg_replace('/^Decision:\s*/i','',$title);elseif($type==='NO_ACTION'){$title='You Let the Opportunity Pass';if(stripos($detail,'decision window closes')!==false)$detail='You were given a chance to act, but you decided not to before the situation changed.';}elseif($type==='LOCATION'&&preg_match('/^\s*(.*?)\s*→\s*(.*?)(?:\s*·.*)?$/u',$detail,$m))$detail='You moved from '.trim($m[1]).' to '.trim($m[2]).'.';$timeline[$second]['personal'][]=['label'=>personal_experience_label($type),'title'=>$title,'detail'=>$detail];}
foreach(array_keys($timeline)as$second)if(!$timeline[$second]['public']&&!$timeline[$second]['personal'])unset($timeline[$second]);krsort($timeline,SORT_NUMERIC);
$outcome=[];if($sim['status']==='COMPLETE'){$q=db()->prepare('SELECT label_text,source_type,source_key FROM plot_outcome_dimensions WHERE plot_id=? AND active=1 ORDER BY sort_order,outcome_dimension_id');$q->execute([$sim['plot_id']]);foreach($q->fetchAll()as$d){$v='UNKNOWN';if($d['source_type']==='FACTOR'){foreach($snap['factors']as$f)if($f['factor_code']===$d['source_key']){$n=(int)$f['current_value'];$v=$n<35?'LOW':($n<65?'MID':'HIGH');break;}}else{$s=GenericStateService::getByKey($sid,(string)$d['source_key']);if($s['exists'])$v=strtoupper((string)$s['value']);}$outcome[]=trim($d['label_text'].' '.$v);}}
function csrf_field():string{return'<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
function game_time(int $seconds):string{if($seconds>=86400){$days=intdiv($seconds,86400);return$days.'d '.gmdate('H:i:s',$seconds%86400);}if($seconds>=3600)return gmdate('G:i:s',$seconds);return gmdate('i:s',$seconds);}
function ordinal_word(int $number):string{$words=[1=>'first',2=>'second',3=>'third',4=>'fourth',5=>'fifth',6=>'sixth',7=>'seventh'];return$words[$number]??($number.(in_array($number%100,[11,12,13],true)?'th':([1=>'st',2=>'nd',3=>'rd'][$number%10]??'th')));}
function story_moment(int $seconds,int $duration):string{if($duration<86400)return game_time($seconds);$seconds=min(max(0,$seconds),max(0,$duration-1));$day=intdiv($seconds,86400)+1;$hour=(int)gmdate('G',$seconds%86400);$part=$hour<5?'late at night':($hour<12?'sometime in the morning':($hour<17?'sometime in the afternoon':($hour<22?'sometime in the evening':'late at night')));return'On the '.ordinal_word($day).' day, '.$part;}
function story_phase_label(string $phase):string{return['EXPOSITION'=>'The Story Begins','INCITING_INCIDENT'=>'Trouble Emerges','RISING_ACTION'=>'Pressure Builds','CLIMAX'=>'The Decisive Moment','RESOLUTION'=>'Consequences Settle','COMPLETE'=>'Consequences Settle'][$phase]??ucwords(strtolower(str_replace('_',' ',$phase)));}
function personal_experience_label(string $type):string{return['DECISION'=>'What You Did','NO_ACTION'=>'What You Left Undone','LOCATION'=>'Where You Went','KNOWLEDGE'=>'What You Learned','CONSEQUENCE'=>'What Changed for You','INTERACTION'=>'What You Considered'][$type]??'What You Experienced';}
function player_visible_text(string $text):string{$sentences=preg_split('/(?<=[.!?])\s+/u',trim($text))?:[];$sentences=array_values(array_filter($sentences,static fn($sentence)=>!preg_match('/\d+\s*→\s*\d+/u',$sentence)));return trim(implode(' ',$sentences));}
function past_verb(string $verb):string{$lower=strtolower($verb);$map=['am'=>'was','are'=>'were','is'=>'was','begin'=>'began','break'=>'broke','bring'=>'brought','build'=>'built','choose'=>'chose','come'=>'came','do'=>'did','draw'=>'drew','drink'=>'drank','drive'=>'drove','feel'=>'felt','find'=>'found','flee'=>'fled','get'=>'got','give'=>'gave','go'=>'went','hear'=>'heard','hold'=>'held','keep'=>'kept','know'=>'knew','lead'=>'led','leave'=>'left','make'=>'made','meet'=>'met','move'=>'moved','put'=>'put','read'=>'read','run'=>'ran','say'=>'said','see'=>'saw','seek'=>'sought','send'=>'sent','sit'=>'sat','speak'=>'spoke','stand'=>'stood','study'=>'studied','take'=>'took','tell'=>'told','think'=>'thought','write'=>'wrote'];if(isset($map[$lower]))return$map[$lower];if(preg_match('/ed$/',$lower))return$lower;if(preg_match('/[^aeiou]y$/',$lower))return substr($lower,0,-1).'ied';if(preg_match('/e$/',$lower))return$lower.'d';return$lower.'ed';}
function observer_narrative(string $name,string $text):string{if($text==='')return$name.' acted while the situation continued to change.';if(preg_match('/^You\s+([A-Za-z]+)(.*)$/su',$text,$m))$text=$name.' '.past_verb($m[1]).$m[2];$text=preg_replace('/\b[Yy]ou\b/u',$name,$text);$text=preg_replace('/\b[Yy]our\b/u','their',$text);return$text;}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($sim['title'])?> · Toinky</title><style>
