line-pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.timeline-pair.solo{grid-template-columns:1fr}.timeline-entry{background:#fff;border-radius:10px;padding:12px;border-left:4px solid #6366f1}.timeline-entry.personal{border-left-color:#f59e0b;background:#fffaf0}.entry-label{font-size:12px;letter-spacing:.01em;font-weight:800}.timeline-entry h3{font-size:15px;margin:5px 0}.timeline-entry p{margin:0;line-height:1.45}.live-note{font-size:12px;color:#64748b;margin-top:-8px;margin-bottom:14px}.decision-alert{display:inline-block;background:#7c3aed;color:#fff;border-radius:999px;padding:4px 9px;font-size:11px;font-weight:850;margin-bottom:6px}@media(max-width:800px){.layout{grid-template-columns:1fr}.identity-grid{grid-template-columns:1fr}.barin{align-items:flex-start;flex-wrap:wrap}.timeline-pair{grid-template-columns:1fr}}
</style></head><body><div id="game-live" data-status="<?=e($sim['status'])?>"><header class="bar"><div class="barin"><div><b><?=e($sim['title'])?></b><div class="muted"><?=e(story_phase_label((string)$sim['current_phase']))?> · <?=e(story_moment($wallElapsed,$playDuration))?></div></div><div class="progress"><span style="width:<?=min(100,round(100*$wallElapsed/max(1,$playDuration)))?>%"></span></div><a href="./">My Games</a></div></header><main class="shell" aria-live="polite"><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><?php if($rated):?><p class="card">Thank you for rating this story.</p><?php endif;?>
