<section class="card briefing"><small>Your Story Briefing</small><h1>The Situation</h1><p><?=e((string)($sim['scenario_text']?:($sim['title'].' takes place in '.$sim['setting_name'].'.')))?></p><?php if($character):?><p><b>You Are <?=e($character['name'])?>.</b> <?=e($character['description'])?></p><?php endif;?></section>
<div class="layout"><div><section class="card"><h2>Live Story Timeline</h2><p class="live-note">Newest events appear first. Public events and your character’s experience share the same chronological row.</p><?php if(!$timeline):?><p class="muted">The story is beginning…</p><?php endif;?><div class="timeline"><?php foreach($timeline as$second=>$row):$both=!empty($row['public'])&&!empty($row['personal']);?><article class="timeline-row"><div class="timeline-time"><?=e(story_moment($displaySecond((int)$second),$playDuration))?></div><div class="timeline-pair <?=$both?'':'solo'?>"><?php if($row['public']):?><div><?php foreach($row['public']as$item):?><section class="timeline-entry"><div class="entry-label">What Happened Around You · <?=e($item['label'])?></div><h3><?=e($item['title'])?></h3><p><?=e($item['detail'])?></p></section><?php endforeach;?></div><?php endif;?><?php if($row['personal']):?><div><?php foreach($row['personal']as$item):?><section class="timeline-entry personal"><div class="entry-label">What You Experienced · <?=e($item['label'])?></div><h3><?=e($item['title'])?></h3><p><?=e($item['detail'])?></p></section><?php endforeach;?></div><?php endif;?></div></article><?php endforeach;?></div></section></div><aside>
